package com.aadil.jobtracker.UserService;import com.aadil.jobtracker.UserRepository.SortDirection;import com.aadil.jobtracker.UserRepository.UserRepository;import com.aadil.jobtracker.UserRepository.UserSortField;import com.aadil.jobtracker.Validation.UserRequestDTO;import com.aadil.jobtracker.Validation.UserResponseDTO;import com.aadil.jobtracker.entity.UserEntity;import com.aadil.jobtracker.exceptions.UserAlreadyExistsException;import com.aadil.jobtracker.responses.PagedResponse;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.stereotype.Service;import java.util.HashSet;import java.util.List;import java.util.Optional;import java.util.Set;@Service@RequiredArgsConstructorpublic class UserServiceImp implements UserService{    private final UserRepository userRepository;    private UserEntity mapToTable (UserRequestDTO dto){        UserEntity user = new UserEntity();        user.setRoles(dto.getRoles());        user.setPassword(dto.getPassword());        user.setEmail(dto.getEmail());        user.setName(dto.getName());        return userRepository.save(user);    }    private UserResponseDTO mapToDTO (UserEntity user){        return new UserResponseDTO(user.getId(),user.getName(),user.getEmail());    }    @Override    public UserResponseDTO createUser(UserRequestDTO dto) {        if (userRepository.existsByName(dto.getName())){            throw new RuntimeException("Username already exists: "+dto.getName());        }        if (userRepository.existsByEmail(dto.getEmail())){            throw new RuntimeException("Email already exists: "+dto.getName());        }        UserEntity user = mapToTable(dto);        return mapToDTO(user);    }    @Override    public List<UserResponseDTO> createUsers(List<UserRequestDTO> dtos) {        Set<String> emails = new HashSet<>();        for (UserRequestDTO dto : dtos) {            if (!emails.add(dto.getEmail())) {                throw new UserAlreadyExistsException("User is already exists within the email: " + dto.getEmail());            }            List<String> dtoEmails = dtos.stream().map(UserRequestDTO::getEmail).toList();            List<UserEntity> existingUser = userRepository.findByEmailsIn(dtoEmails);            if (!existingUser.isEmpty()) {                throw new UserAlreadyExistsException("Duplicate email found within the table: " + dto.getEmail());            }        }        List<UserEntity> createdUser = dtos.stream().map(this::mapToTable).toList();        List<UserEntity> savedUser = userRepository.saveAll(createdUser);        return savedUser.stream().map(this::mapToDTO).toList();    }    @Override    public Optional<UserResponseDTO> getUser(Long id) {        UserEntity user = userRepository.findById(id).orElseThrow(()->new UsernameNotFoundException("User NOT found: "+ id));        return Optional.of(mapToDTO(user));    }    @Override    public Optional<List<UserResponseDTO>> getUsersById(List<Long> ids) {        List<UserEntity> users = userRepository.findAllById(ids).stream().toList();        return Optional.of(users.stream().map(this::mapToDTO).toList());    }    @Override    public PagedResponse<UserResponseDTO> getAllUsers(String search, int size, int pageNumber, UserSortField userSortField, SortDirection sortDirection) {        if (search != null && search.isBlank()){            search = search.trim();        }        if (search != null && search.length() > 50){            throw new RuntimeException("Search should be under 50 characters");        }        if (size < -1 ) size = 5;        if (size > 50) size = 50;        if (pageNumber < -1) pageNumber = 0;        if (pageNumber > 50) pageNumber = 50;        if (userSortField == null){            userSortField = UserSortField.ID;        }        if (sortDirection == null){            sortDirection = SortDirection.DESC;        }        Sort sort = (sortDirection == SortDirection.DESC)?                Sort.by(Sort.Direction.DESC.name().toLowerCase()):Sort.by(Sort.Direction.ASC.name().toLowerCase());        Pageable pageable = PageRequest.of(pageNumber,size,sort);        Page<UserEntity> user;        if (search == null){            user = userRepository.findAll(pageable);        }        else {            user = userRepository.findNameContainingIgnoreCaseAndEmailContainingIgnoreCase(search,search,pageable);        }        List<UserResponseDTO> contents = user.getContent().stream().map(this::mapToDTO).toList();        return new PagedResponse<>(contents,user.getNumber(),user.getSize(), user.getTotalPages(), user.getTotalElements(),user.isLast());    }    @Override    public Optional<UserResponseDTO> updateUser(Long id, UserRequestDTO dto) {        UserEntity user = userRepository.findById(id).orElseThrow(()->new UsernameNotFoundException("User NOT found: "+ id));        user.setName(dto.getName());        user.setEmail(dto.getEmail());        user.setPassword(dto.getPassword());        user.setRoles(dto.getRoles());        UserEntity savedUsers = userRepository.save(user);        return Optional.of(mapToDTO(savedUsers));    }    @Override    public void deleteUser(Long id,boolean confirm) {        if (!confirm){            throw new IllegalArgumentException("Deletion cancelled, Type TRUE to continue");        }        UserEntity user = userRepository.findById(id).orElseThrow(()->new UsernameNotFoundException("User NOT found: "+id));        userRepository.delete(user);    }    @Override    public void deleteAll(boolean confirm) {        if (!confirm){            throw new IllegalArgumentException("Deletion cancelled, Type TRUE to delete All");        }        userRepository.deleteAll();    }    @Override    public void deleteById(List<Long> ids,boolean confirm) {        if (!confirm){            throw new IllegalArgumentException("Deletion cancelled, Type TRUE to delete by ID");        }        userRepository.deleteAllById(ids);    }}